        ".checkbox-symbol {\n  position: absolute;\n  width: 0;\n  height: 0;\n  pointer-events: none;\n  user-select: none;\n}\n\n.checkbox-container {\n  box-sizing: border-box;\n  background: #ffffff;\n  color: #222;\n  height: 64px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  flex-flow: row wrap;\n}\n\n.checkbox-container * {\n  box-sizing: border-box;\n}\n\n.checkbox-input {\n  position: absolute;\n  visibility: hidden;\n}\n\n.checkbox {\n  user-select: none;\n  cursor: pointer;\n  padding: 6px 8px;\n  border-radius: 6px;\n  overflow: hidden;\n  transition: all 0.3s ease;\n  display: flex;\n}\n\n.checkbox:not(:last-child) {\n  margin-right: 6px;\n}\n\n.checkbox:hover {\n  background: rgba(0, 119, 255, 0.06);\n}\n\n.checkbox span {\n  vertical-align: middle;\n  transform: translate3d(0, 0, 0);\n}\n\n.checkbox span:first-child {\n  position: relative;\n  flex: 0 0 18px;\n  width: 18px;\n  height: 18px;\n  border-radius: 4px;\n  transform: scale(1);\n  border: 1px solid #cccfdb;\n  transition: all 0.3s ease;\n}\n\n.checkbox span:first-child svg {\n  position: absolute;\n  top: 3px;\n  left: 2px;\n  fill: none;\n  stroke: #fff;\n  stroke-dasharray: 16px;\n  stroke-dashoffset: 16px;\n  transition: all 0.3s ease;\n  transform: translate3d(0, 0, 0);\n}\n\n.checkbox span:last-child {\n  padding-left: 8px;\n  line-height: 18px;\n}\n\n.checkbox:hover span:first-child {\n  border-color: #0077ff;\n}\n\n.checkbox-input:checked + .checkbox span:first-child {\n  background: #0077ff;\n  border-color: #0077ff;\n  animation: zoom-in-out 0.3s ease;\n}\n\n.checkbox-input:checked + .checkbox span:first-child svg {\n  stroke-dashoffset: 0;\n}\n\n@keyframes zoom-in-out {\n  50% {\n    transform: scale(0.9);\n  }\n}",
